def solve(grid):
    # Find the two non‑zero colours. The one that occurs more often is the
    # “shape” colour, the other one is the “marker” colour.
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if len(counts) != 2:
        # If there are not exactly two non‑zero colours we cannot apply the rule.
        # Return a 3×3 zero grid (or could raise an error).
        return [[0,0,0],[0,0,0],[0,0,0]]

    shape_colour = max(counts, key=counts.get)
    marker_colour = min(counts, key=counts.get)

    # Compute the bounding box of the shape colour.
    min_r = max_r = min_c = max_c = None
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == shape_colour:
                if min_r is None:
                    min_r = max_r = r
                    min_c = max_c = c
                else:
                    if r < min_r: min_r = r
                    if r > max_r: max_r = r
                    if c < min_c: min_c = c
                    if c > max_c: max_c = c

    height = max_r - min_r + 1
    width  = max_c - min_c + 1

    # Partition the bounding box into a 3×3 grid.
    # For each cell of the shape record which sub‑region it belongs to.
    occupied = set()
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == shape_colour:
                # map row and column to region indices 0,1,2
                region_r = (r - min_r) * 3 // height
                region_c = (c - min_c) * 3 // width
                # clamp to the last region in case of rounding edge cases
                if region_r > 2: region_r = 2
                if region_c > 2: region_c = 2
                occupied.add((region_r, region_c))

    # Build the 3×3 output grid.
    out = [[marker_colour if (i,j) in occupied else 0 for j in range(3)] for i in range(3)]
    return out

